package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import jakarta.servlet.http.HttpServletRequest;
import java.util.function.Function;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real orchestration against explicit authority/object/supervisor doubles. No deployed isolation/provider claim. */
class TaskProfessionalHostOrchestratorTest {
 final TaskProfessionalHostAccess hosts=mock(TaskProfessionalHostAccess.class);final TaskProfessionalHostAccess.Handle handle=mock(TaskProfessionalHostAccess.Handle.class);
 final TaskProfessionalRuntimeService runtime=mock(TaskProfessionalRuntimeService.class);final TaskProfessionalPromptCompiler compiler=mock(TaskProfessionalPromptCompiler.class);
 final TaskInvocationPackages packages=mock(TaskInvocationPackages.class);final TaskNodeProducerAuthority producers=mock(TaskNodeProducerAuthority.class);final TaskProfessionalObjectLedger ledger=mock(TaskProfessionalObjectLedger.class);
 final RuntimeObjectTransport objects=mock(RuntimeObjectTransport.class);final TaskProfessionalObjectRegistration registration=mock(TaskProfessionalObjectRegistration.class);final TaskProfessionalSupervisor supervisor=mock(TaskProfessionalSupervisor.class);
 final EnterpriseAccess.Admission a=mock(EnterpriseAccess.Admission.class,RETURNS_DEEP_STUBS);final TaskProfessionalRuntimeService.Envelope metadata=mock(TaskProfessionalRuntimeService.Envelope.class),envelope=mock(TaskProfessionalRuntimeService.Envelope.class);
 final TaskProfessionalPromptCompiler.CompiledPrompt prompt=mock(TaskProfessionalPromptCompiler.CompiledPrompt.class);final TaskProfessionalHostAccess.InputContent input=mock(TaskProfessionalHostAccess.InputContent.class);final TaskNodeInputAuthority.Verified registeredInput=mock(TaskNodeInputAuthority.Verified.class);
 final TaskInvocationPackages.Read role=mock(TaskInvocationPackages.Read.class),instructions=mock(TaskInvocationPackages.Read.class),profile=mock(TaskInvocationPackages.Read.class);
 final TaskNodeProducerAuthority.LeasedProduction producer=mock(TaskNodeProducerAuthority.LeasedProduction.class);final TaskProfessionalObjectLedger.Intent intent=mock(TaskProfessionalObjectLedger.Intent.class);final TaskProfessionalObjectLedger.Attempt attempt=mock(TaskProfessionalObjectLedger.Attempt.class);final RuntimeObjectTransport.VerifiedTransfer transfer=mock(RuntimeObjectTransport.VerifiedTransfer.class);final TaskProfessionalObjectRegistration.Registered registered=mock(TaskProfessionalObjectRegistration.Registered.class);
 final TaskRuntimeJournal journal=mock(TaskRuntimeJournal.class);final TaskRuntimeJournal.Dispatch dispatched=mock(TaskRuntimeJournal.Dispatch.class);final String command="10000000-0000-4000-8000-000000000111";
 final TaskProfessionalHostOrchestrator service;final String session="10000000-0000-4000-8000-000000000001",project="10000000-0000-4000-8000-000000000002";final com.fasterxml.jackson.databind.node.ObjectNode launch=new JsonMapper().createObjectNode().put("state","PREPARE").put("session_id",session);
 TaskProfessionalHostOrchestratorTest()throws Exception{
  when(hosts.execute(eq(handle),any())).thenAnswer(call->((Function<EnterpriseAccess.Admission,?>)call.getArgument(1)).apply(a));when(a.formalProof().identity().project()).thenReturn(project);when(hosts.consumeInput(handle)).thenReturn(input);when(hosts.envelope(handle,a)).thenReturn(metadata);when(metadata.input()).thenReturn(registeredInput);when(envelope.input()).thenReturn(registeredInput);
  var rolePin=basis(3);var promptPin=basis(4);var profilePin=basis(5);when(compiler.roleArtifact(metadata)).thenReturn(rolePin);when(compiler.promptArtifact(metadata,role)).thenReturn(promptPin);when(compiler.profileArtifact(metadata)).thenReturn(profilePin);
  when(packages.readWorker(hosts,handle,project,rolePin)).thenReturn(role);when(packages.readWorker(hosts,handle,project,promptPin)).thenReturn(instructions);when(packages.readWorker(hosts,handle,project,profilePin)).thenReturn(profile);when(compiler.compile(metadata,input,role,instructions,profile)).thenReturn(prompt);when(runtime.compileEnvelope(a,registeredInput,prompt)).thenReturn(envelope);when(producers.requireLeased(a,registeredInput)).thenReturn(producer);when(ledger.prepare(producer,envelope)).thenReturn(intent);when(ledger.attempt(producer,envelope,intent)).thenReturn(attempt);
  when(objects.transferVerified(eq(attempt),any())).thenAnswer(c->{((S3ObjectReader.Admission)c.getArgument(1)).requireCurrent();return transfer;});when(registration.register(producer,envelope,attempt,transfer)).thenReturn(registered);when(registration.readVerified(producer,envelope,attempt,transfer)).thenReturn(registered);when(runtime.prepareLaunch(envelope,registered,input,prompt)).thenReturn(launch);
  when(journal.prepareStep(envelope,registered,command)).thenReturn(dispatched);when(journal.requireStep(envelope,registered,command)).thenReturn(dispatched);
  service=new TaskProfessionalHostOrchestrator(hosts,runtime,compiler,packages,producers,ledger,objects,registration,supervisor,journal,mock(PermissionSchema.class));
 }
 @Test void preparedBytesRequirePhysicalInputPackagesAndGuardedOriginalRegistration()throws Exception{var prepared=service.prepare(handle,command);assertEquals(launch,prepared.launch());var order=inOrder(hosts,packages,ledger,objects,registration,journal,runtime);order.verify(hosts).consumeInput(handle);order.verify(packages).readWorker(eq(hosts),eq(handle),eq(project),any());order.verify(ledger).prepare(producer,envelope);order.verify(ledger).attempt(producer,envelope,intent);order.verify(objects).transferVerified(eq(attempt),any());order.verify(registration).register(producer,envelope,attempt,transfer);order.verify(journal).prepareStep(envelope,registered,command);order.verify(runtime).prepareLaunch(envelope,registered,input,prompt);verifyNoInteractions(supervisor);verify(runtime,never()).registerSession(any(),any(),any(),any(),any(),any());}
 @Test void initialPhysicalReadFailureCannotPrepareOrRegisterAnything()throws Exception{when(hosts.consumeInput(handle)).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->service.prepare(handle,command));verifyNoInteractions(packages,ledger,objects,registration,supervisor);}
 @Test void preparationOnlyEnvelopeNeverCrosses075ProducerBoundary()throws Exception{doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(envelope).requireProductionReady();assertThrows(TenantAccessException.class,()->service.prepare(handle,command));verifyNoInteractions(ledger,objects,registration,supervisor);}
 @Test void revocationAtExternalTransferGuardPreventsRegistration()throws Exception{doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(registration).requireTransferCurrent(producer,envelope,attempt);assertThrows(TenantAccessException.class,()->service.prepare(handle,command));verify(registration,never()).register(any(),any(TaskProfessionalRuntimeService.Envelope.class),any(),any());verifyNoInteractions(supervisor);}
 @Test void wrongPreparedSessionNeverFetchesIndependentAdmission()throws Exception{assertThrows(TenantAccessException.class,()->service.admit(mock(HttpServletRequest.class),handle,"10000000-0000-4000-8000-000000000099",command));verifyNoInteractions(supervisor);}
 @Test void originalPreparedReplyCannotEscapeAfterLeaseRevocation()throws Exception{var prepared=service.prepare(handle,command);when(hosts.execute(eq(handle),any())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,prepared::launch);}
 @Test void missingOriginalDispatchCannotEscapeRecovery()throws Exception{var prepared=service.prepare(handle,command);when(journal.requireStep(envelope,registered,command)).thenThrow(new TenantAccessException(ErrorCode.CONTENT_MISMATCH));assertThrows(TenantAccessException.class,prepared::launch);}
 static PermissionProtocol.Basis basis(int n){return new PermissionProtocol.Basis(String.format("10000000-0000-4000-8000-%012d",n),"a".repeat(64));}
}
